#!/bin/bash
# Build Meter.app. `./build.sh install` also replaces /Applications/Meter.app and relaunches it.
# The icon is generated by Tools/make-icon.swift (`swift Tools/make-icon.swift titanium Resources/AppIcon.icns`).
set -euo pipefail
cd "$(dirname "$0")"

APP=build/Meter.app
rm -rf build
mkdir -p "$APP/Contents/MacOS" "$APP/Contents/Resources"
swiftc -O -swift-version 5 -target arm64-apple-macos13.0 \
  -framework AppKit -framework ServiceManagement \
  Sources/*.swift -o "$APP/Contents/MacOS/Meter"
cp Resources/Info.plist "$APP/Contents/Info.plist"
cp Resources/AppIcon.icns "$APP/Contents/Resources/AppIcon.icns"
# Bundle id predates the rename; keeping it preserves settings and the login item.
codesign --force --sign - --identifier local.usagebar "$APP"
echo "Built $APP"

if [ "${1:-}" = "install" ]; then
  pkill -x Meter || true
  pkill -x UsageBar || true
  sleep 1
  rm -rf /Applications/Meter.app /Applications/UsageBar.app
  cp -R "$APP" /Applications/Meter.app
  open /Applications/Meter.app
  echo "Installed and launched /Applications/Meter.app"
fi
